import sys

def main():
    data = sys.stdin.read().split()
    m = int(data[0])
    edges = [(data[1 + 2 * i], data[2 + 2 * i]) for i in range(m)]
    children = {}
    parent = {}
    seen = set()
    dup = False
    for a, b in edges:
        children.setdefault(a, [])
        children.setdefault(b, [])
    for a, b in edges:
        if (a, b) in seen:
            dup = True
        else:
            seen.add((a, b))
            children[a].append(b)
            parent[b] = a
    if any(len(c) > 2 for c in children.values()):
        print('E1')
        return
    if dup:
        print('E2')
        return
    state = {}
    for v in children:
        if v in state:
            continue
        path = []
        u = v
        while u is not None and u not in state:
            state[u] = 1
            path.append(u)
            u = parent.get(u)
        if u is not None and state[u] == 1:
            print('E3')
            return
        for w in path:
            state[w] = 2
    roots = [v for v in children if v not in parent]
    if len(roots) > 1:
        print('E4')
        return
    root = roots[0]
    out = ['(' + root]
    stack = [[root, 0]]
    while stack:
        top = stack[-1]
        ch = children[top[0]]
        if top[1] < len(ch):
            c = ch[top[1]]
            top[1] += 1
            out.append('(' + c)
            stack.append([c, 0])
        else:
            out.append(')')
            stack.pop()
    print(''.join(out))

